// recipe: virtual-input
// args: mode=s x=n y=n button=n
// serves: the-acceptance-channel-replaces-its-staged-pointer, cross-player-drag-use-feedback, context-menu-does-not-block-the-pointer
// returns: ok, mode, answer, installed, buttonPatches, held, down, up, pointerX, pointerY, inputX, inputY, error, detail
//
// The acceptance channel's virtual mouse: installs the Harmony patches on `UnityEngine.Input.mousePosition` (a managed getter) and on
// `GetMouseButton`/`GetMouseButtonDown`/`GetMouseButtonUp` (internal calls, which HarmonyX patches through its NATIVE detour backend — the backend
// answered `patched` for all three on this build, so "no IL body" was never a verdict), then stages a pointer and/or button state the game's own reads
// answer instead of the real mouse.
//  - mode=install        patch everything; `answer` is the per-method report the seam builds
//  - mode=move           stage the pointer at (x, y) — the game's screen coordinates, origin bottom-left
//  - mode=press          press `button` (DOWN this frame, HELD afterwards)
//  - mode=release        release `button` (UP this frame only)
//  - mode=clear          drop the staged pointer
//  - mode=clear-buttons  drop every staged button
//  - mode=uninstall      remove the patches and the staged state; the real input answers again
//  - mode=report         read the three Input answers and the staged state without changing anything
//
// ONE LINE, because the evaluator compiles a submission as one top-level expression: a body with newlines is refused as `(1,1): InteractiveHost`
// (measured 2026-10-27 — this recipe answered as separate probes and died only when written multi-line).
((System.Func<string>)(() => { var mode = {{s:mode}}; var x = {{n:x}}; var y = {{n:y}}; var button = (int){{n:button}}; var findType = new System.Func<string, System.Type>((simpleName) => { var assemblies = System.AppDomain.CurrentDomain.GetAssemblies(); for (var i = 0; i < assemblies.Length; i++) { System.Type[] types; try { types = assemblies[i].GetTypes(); } catch { continue; } for (var t = 0; t < types.Length; t++) { if (types[t].Name == simpleName) { return types[t]; } } } return null; }); var vi = findType("VirtualInput"); if (vi == null) { return "{\"ok\":false,\"error\":\"no-VirtualInput\"}"; } const System.Reflection.BindingFlags Flags = System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic; var answer = ""; var install = vi.GetMethod("Install", Flags); if (mode == "install") { var args = new object[] { false }; answer = (string)install.Invoke(null, args); } else if (mode == "move") { install.Invoke(null, new object[] { false }); vi.GetMethod("MoveTo", Flags).Invoke(null, new object[] { x, y }); answer = "moved"; } else if (mode == "press") { install.Invoke(null, new object[] { false }); vi.GetMethod("Press", Flags).Invoke(null, new object[] { button }); answer = "pressed"; } else if (mode == "release") { vi.GetMethod("Release", Flags).Invoke(null, new object[] { button }); answer = "released"; } else if (mode == "clear") { vi.GetMethod("Clear", Flags).Invoke(null, null); answer = "cleared"; } else if (mode == "clear-buttons") { vi.GetMethod("ClearButtons", Flags).Invoke(null, null); answer = "buttons cleared"; } else if (mode == "uninstall") { vi.GetMethod("Uninstall", Flags).Invoke(null, null); answer = "uninstalled"; } else if (mode == "report") { answer = "reported"; } else { return "{\"ok\":false,\"error\":\"bad-mode\",\"detail\":\"install, move, press, release, clear, clear-buttons, uninstall or report\"}"; } var installed = (bool)vi.GetProperty("Installed", Flags).GetValue(null, null); var patches = (int)vi.GetProperty("ButtonPatches", Flags).GetValue(null, null); var held = UnityEngine.Input.GetMouseButton(button); var down = UnityEngine.Input.GetMouseButtonDown(button); var up = UnityEngine.Input.GetMouseButtonUp(button); var mouseKey = button == 0 ? UnityEngine.KeyCode.Mouse0 : (button == 1 ? UnityEngine.KeyCode.Mouse1 : UnityEngine.KeyCode.Mouse2); var keyHeld = UnityEngine.Input.GetKey(mouseKey); var keyDown = UnityEngine.Input.GetKeyDown(mouseKey); var keyUp = UnityEngine.Input.GetKeyUp(mouseKey); var px = "-1"; var py = "-1"; var tryGet = vi.GetMethod("TryGetStaged", Flags); if (tryGet != null) { var staged = new object[] { null }; if ((bool)tryGet.Invoke(null, staged)) { var v = (UnityEngine.Vector3)staged[0]; px = v.x.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture); py = v.y.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture); } } var input = UnityEngine.Input.mousePosition; var text = (answer ?? "").Replace("\\", "/").Replace("\"", "''"); return "{\"ok\":true,\"mode\":\"" + mode + "\",\"answer\":\"" + text + "\",\"installed\":" + (installed ? "true" : "false") + ",\"buttonPatches\":" + patches.ToString(System.Globalization.CultureInfo.InvariantCulture) + ",\"held\":" + (held ? "true" : "false") + ",\"down\":" + (down ? "true" : "false") + ",\"up\":" + (up ? "true" : "false") + ",\"keyHeld\":" + (keyHeld ? "true" : "false") + ",\"keyDown\":" + (keyDown ? "true" : "false") + ",\"keyUp\":" + (keyUp ? "true" : "false") + ",\"pointerX\":\"" + px + "\",\"pointerY\":\"" + py + "\",\"inputX\":\"" + input.x.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) + "\",\"inputY\":\"" + input.y.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) + "\"}"; }))()
